package com.example.downloads;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;

import org.junit.jupiter.api.Test;

class DownloadHeadersSecurityTest {
    @Test
    void benignControl() {
        assertEquals("attachment; filename=\"report.txt\"", DownloadHeaders.disposition("report.txt"));
    }

    @Test
    void securityKeepsOneHeaderLine() {
        String value = DownloadHeaders.disposition("report.txt\r\nSet-Cookie: session=x");
        assertFalse(value.contains("\r") || value.contains("\n"));
    }
}
